data.variablesTransform:
{
  "payload": {
    "update": (
			$ids := $merge($keys($).{ $ & "Id": $lookup($$, $).id });
			$omitKeys := $.$sift(function($v, $k) { $not($isObject($v)) and $k != "id" and $isNotNilOrEmpty($v) });
			$merge([$omitKeys, $ids])
      /*loops over all data from form and writes only
      the selected ids, omitting the objects from
      the mutation transform*/
		),
    "where":{"id":id}
  }
}

data.query:
query Query($where: LoadStageWhereInput, $orderBy: [LoadStageOrderByInput!], $first: Int, $after: String) {
  loadStage(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code
        default
      }
    }
  }
}

